  ('mariner', '/ˈmɛr.ɪ.nər/', '水手', 'A person who navigates or operates a ship.'),
  ('bovine', '/ˈboʊ.vaɪn/', '牛的；与牛相关的', 'Relating to or resembling cattle, especially in characteristics.'),
  ('convergent', '/kənˈvɜr.dʒənt/', '会聚的；趋同的', 'Tending to come together from different directions.'),
  ('maelstrom', '/ˈmeɪl.strəm/', '漩涡', 'A powerful whirlpool in a body of water.'),
  ('morass', '/məˈræs/', '泥沼；困境', 'A complicated or confusing situation that is difficult to escape from.'),
  ('machination', '/ˌmæʃɪˈneɪʃən/', '阴谋；策划', 'A plot or scheme, especially one with sinister intent.')
  ) AS v(headword, ipa, def_zh, def_en)
 WHERE lower(w.headword) = v.headword
   AND w.def_zh IS NULL;        -- ← 护栏:只填空,绝不覆盖库里已有的释义

-- ② 例句
